<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceAccountService{
 public static function bootstrap(Actor $a):array{Guard::any($a,[Capabilities::FINANCE_VIEW,Capabilities::ACCOUNTING_VIEW,Capabilities::ACCOUNT_MANAGE,Capabilities::SALES_CREATE,Capabilities::RECEIPT_CREATE,Capabilities::SUPPLIER_PAYMENT,Capabilities::EXPENSE_CREATE,Capabilities::BANK_RECONCILE,Capabilities::PAYROLL_PAY]);$db=Db::wpdb();return['accounts'=>(array)$db->get_results($db->prepare("SELECT id,code,name,type,subtype FROM ".Db::table('accounts')." WHERE company_id=%d AND active=1 ORDER BY code",$a->companyId),ARRAY_A),'expense_heads'=>(array)$db->get_results($db->prepare("SELECT id,code,name,expense_account_id FROM ".Db::table('expense_heads')." WHERE company_id=%d AND active=1 ORDER BY name",$a->companyId),ARRAY_A)];}
 public static function createAccount(Actor $a,string $code,string $name,string $type,string $subtype=''):array{Guard::cap($a,Capabilities::ACCOUNT_MANAGE);$code=strtoupper(trim($code));$name=trim($name);$type=strtolower(trim($type));$subtype=strtolower(trim($subtype));if($code===''||$name===''||!in_array($type,['asset','liability','equity','income','expense'],true))throw new DomainException('Valid account code, name and type are required.','account_fields_invalid',422);if(in_array($subtype,['cash','bank','upi'],true)&&$type!=='asset')throw new DomainException('Cash, Bank and UPI ledgers must be Asset accounts.','payment_account_type_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('accounts'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'type'=>$type,'subtype'=>$subtype?:null,'active'=>1],'Account code already exists.','account_duplicate');$id=(int)$db->insert_id;Audit::add($a,'account.create','account',$id,['code'=>$code,'type'=>$type,'subtype'=>$subtype]);return['id'=>$id,'code'=>$code,'name'=>$name,'type'=>$type,'subtype'=>$subtype?:null];}
 public static function createExpenseHead(Actor $a,string $code,string $name,int $accountId):array{Guard::cap($a,Capabilities::ACCOUNT_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name===''||$accountId<1)throw new DomainException('Expense head code, name and expense account are required.','expense_head_fields_invalid',422);$account=AccountingService::account($a,$accountId);if((string)$account['type']!=='expense')throw new DomainException('Expense Head must point to an Expense ledger.','expense_head_account_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('expense_heads'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'expense_account_id'=>$accountId,'active'=>1],'Expense Head code already exists.','expense_head_duplicate');$id=(int)$db->insert_id;Audit::add($a,'expense_head.create','expense_head',$id,['code'=>$code,'expense_account_id'=>$accountId]);return['id'=>$id,'code'=>$code,'name'=>$name,'expense_account_id'=>$accountId];}
}
